select 'feed|' || f.id || '|' || p.name || '|' || f.consecutive_failures || '|' || coalesce(to_char(f.last_success_at, 'HH24:MI'), 'never') || '|' || coalesce(f.last_error, '-') || '|' || (SELECT count(*) FROM articles a WHERE a.publisher_id = f.publisher_id AND a.fetched_at > now() - interval '1 hour') || ' new' FROM feeds f JOIN publishers p ON p.id = f.publisher_id WHERE f.id IN (216, 254, 284, 296, 521, 538, 547, 579, 1038, 1519) ORDER BY f.id;
select 'ok|' || count(*) FILTER (WHERE f.last_success_at > now() - interval '30 minutes') || ' of 10 fixed feeds succeeded in the last 30 min' FROM feeds f WHERE f.id IN (216, 254, 284, 296, 521, 538, 547, 579, 1038, 1519);
select 'unavailable|' || count(*) FROM publishers WHERE feed_status = 'unavailable' AND id IN (997, 962, 1524, 225, 524, 272, 279, 1003, 266, 218, 259, 1065, 1541, 1509);
